<template><div class="titlebar"><div><h1>数据集管理</h1><p class="sub">LeRobot 数据集、文件和 Episode 索引</p></div><el-button type="primary" @click="createVisible=true">+ 新建 Dataset</el-button></div>
<div class="panel"><el-table :data="items" v-loading="loading" stripe><el-table-column prop="name" label="数据集" min-width="180"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="total_episodes" label="Episodes" width="105"/><el-table-column prop="total_frames" label="Frames" width="110"/><el-table-column prop="fps" label="FPS" width="80"/><el-table-column label="操作" min-width="320"><template #default="{row}"><div class="actions"><el-button size="small" @click="$router.push(`/datasets/${row.id}/episodes`)">浏览</el-button><el-button size="small" @click="openImport(row)">导入清单</el-button><el-button size="small" @click="runJob(row)">质量检查</el-button><el-popconfirm title="确定删除数据集及其索引？" @confirm="remove(row)"><template #reference><el-button size="small" type="danger" plain>删除</el-button></template></el-popconfirm></div></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="尚无数据集"/></div>
<el-dialog v-model="createVisible" title="新建数据集" width="480"><el-form :model="form" label-width="85px"><el-form-item label="名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="来源"><el-input v-model="form.source" placeholder="lerobot/aloha_sim_transfer_cube_scripted"/></el-form-item></el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog>
<el-dialog v-model="importVisible" title="导入 Dataset 索引清单" width="640"><p class="muted">上传 manifest.json。原始 parquet/mp4 文件可在本窗口另行上传至 MinIO；清单中的 data_file、video_file 使用相对于数据集目录的路径。</p><el-upload :auto-upload="false" :limit="1" accept=".json" :on-change="selectManifest"><el-button>选择 manifest.json</el-button></el-upload><div style="margin-top:20px"><el-input v-model="filePath" placeholder="对象路径，如 data/chunk-000/file-000.parquet"/><input type="file" @change="selectRaw" style="margin-top:8px"/><el-button :disabled="!rawFile" style="margin-top:8px" @click="sendRaw">上传原始文件</el-button></div><template #footer><el-button @click="importVisible=false">关闭</el-button><el-button type="primary" :disabled="!manifest" @click="sendManifest">导入索引</el-button></template></el-dialog></template>
<script setup>
import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {listDatasets,createDataset,deleteDataset,importManifest,uploadFile} from '../api/dataset';import {createJob} from '../../job/api/job'
const router=useRouter(),items=ref([]),loading=ref(false),createVisible=ref(false),importVisible=ref(false),current=ref(null),manifest=ref(null),rawFile=ref(null),filePath=ref(''),form=ref({name:'',description:'',source:''})
function fail(e){ElMessage.error(e.response?.data?.error||e.message)}
async function refresh(){loading.value=true;try{items.value=await listDatasets()}catch(e){fail(e)}finally{loading.value=false}}
async function create(){try{await createDataset(form.value);createVisible.value=false;form.value={name:'',description:'',source:''};await refresh()}catch(e){fail(e)}}
async function remove(d){try{await deleteDataset(d.id);await refresh()}catch(e){fail(e)}}
async function runJob(d){try{await createJob(d.id);ElMessage.success('任务已创建');router.push('/jobs')}catch(e){fail(e)}}
function openImport(d){current.value=d;manifest.value=null;rawFile.value=null;importVisible.value=true}
function selectManifest(f){manifest.value=f.raw}
function selectRaw(e){rawFile.value=e.target.files?.[0]}
async function sendManifest(){try{await importManifest(current.value.id,JSON.parse(await manifest.value.text()));ElMessage.success('索引导入成功');importVisible.value=false;await refresh()}catch(e){fail(e)}}
async function sendRaw(){try{await uploadFile(current.value.id,rawFile.value,filePath.value);ElMessage.success('文件已上传')}catch(e){fail(e)}}
onMounted(refresh)
</script>
